package com.rescuefarm.service.seller;
import com.rescuefarm.domain.enums.*;import com.rescuefarm.domain.model.*;import java.util.*;
public final class SellerDashboardAggregator{public SellerDashboardSnapshot aggregate(String sellerId,List<Product> products,List<RescueCampaign> campaigns,List<Post> posts,List<Order> orders,int promotions){String seller=required(sellerId);List<Product>ps=filterProducts(seller,products);List<RescueCampaign>cs=filterCampaigns(seller,campaigns);List<Post>xs=filterPosts(seller,posts);List<Order>os=filterOrders(seller,orders);int activeProducts=0,activeCampaigns=0,mobile=0,pendingPosts=0,pendingOrders=0,delivery=0;double revenue=0,rescued=0;for(Product p:ps)if(p.getStatus()==ProductStatus.ACTIVE)activeProducts++;for(RescueCampaign c:cs){if(c.getStatus()==CampaignStatus.ACTIVE)activeCampaigns++;if(c.getRescueMode()==RescueMode.MOBILE_POINT)mobile++;rescued+=c.getRescuedQuantity();}for(Post p:xs)if(p.getStatus()==PostStatus.PENDING_APPROVAL)pendingPosts++;for(Order o:os){if(o.getStatus()!=OrderStatus.DELIVERED&&o.getStatus()!=OrderStatus.CANCELLED)pendingOrders++;if(o.getFulfillmentType()==FulfillmentType.DELIVERY)delivery++;if(o.getStatus()==OrderStatus.DELIVERED)revenue+=o.getTotalAmount();}os.sort((a,b)->Long.compare(time(b.getCreatedAt()),time(a.getCreatedAt())));List<Order>recent=os.subList(0,Math.min(5,os.size()));return new SellerDashboardSnapshot(ps.size(),activeProducts,cs.size(),activeCampaigns,mobile,xs.size(),pendingPosts,os.size(),pendingOrders,delivery,Math.max(0,promotions),revenue,rescued,recent);}
 private List<Product>filterProducts(String s,List<Product>x){List<Product>o=new ArrayList<>();if(x!=null)for(Product v:x)if(s.equals(v.getSellerId()))o.add(v);return o;}private List<RescueCampaign>filterCampaigns(String s,List<RescueCampaign>x){List<RescueCampaign>o=new ArrayList<>();if(x!=null)for(RescueCampaign v:x)if(s.equals(v.getSellerId()))o.add(v);return o;}private List<Post>filterPosts(String s,List<Post>x){List<Post>o=new ArrayList<>();if(x!=null)for(Post v:x)if(s.equals(v.getSellerId()))o.add(v);return o;}private List<Order>filterOrders(String s,List<Order>x){List<Order>o=new ArrayList<>();if(x!=null)for(Order v:x)if(s.equals(v.getSellerId()))o.add(v);return o;}private static String required(String x){if(x==null||x.trim().isEmpty())throw new IllegalArgumentException("Seller id is required");return x.trim();}private static long time(Date d){return d==null?0:d.getTime();}}
